from decimal import Decimal, ROUND_HALF_UP

from django.db import migrations, models


def _company_regime(company):
    country = (company.country or "").strip().lower()
    currency = (company.currency or "").strip().upper()
    if ("india" in country or country in {"in", "ind", "bharat"}) or (not country and currency == "INR"):
        return "in_gst"
    if ("emirates" in country or "uae" in country.replace(".", "") or country in {"ae", "are", "dubai", "abu dhabi", "sharjah"}) or (not country and currency == "AED"):
        return "ae_vat"
    return "generic"


def backfill_sales_tax(apps, schema_editor):
    """Give existing quotes/invoices a tax system and split old GST into CGST/SGST."""
    two = Decimal("0.01")
    for model_name in ("Quote", "Invoice"):
        Model = apps.get_model("crm", model_name)
        for doc in Model.objects.select_related("company").iterator():
            currency = (doc.currency or "").strip().upper()
            regime = {"INR": "in_gst", "AED": "ae_vat"}.get(currency) or _company_regime(doc.company)
            doc.tax_regime = regime
            tax = Decimal(str(doc.tax_amount or 0))
            if regime == "in_gst" and tax:
                half = (tax / 2).quantize(two, ROUND_HALF_UP)
                doc.cgst_amount, doc.sgst_amount = half, tax - half
            doc.save(update_fields=["tax_regime", "cgst_amount", "sgst_amount"])


